import { Group, Mesh, PlaneGeometry, DoubleSide } from 'three/webgpu';
import { MeshStandardNodeMaterial, texture, float } from 'three/tsl';
import { gsap } from 'gsap';
import { parallaxScroll } from '@/primitives';

export default function createNode(config, ctx) {
  // Root container
  const root = new Group();

  // Geometry: high‑tessellated plane
  const geometry = new PlaneGeometry(1, 1, 64, 64);
  geometry.rotateX(-Math.PI / 2); // face upward

  // Material with placeholders – textures will be attached asynchronously
  const material = new MeshStandardNodeMaterial({
    side: DoubleSide,
    metalness: float(0.5),
    roughness: float(0.6),
    clearcoat: float(0.1),
    envMapIntensity: 1.0,
  });

  // Displacement scale (subtle)
  material.displacementScale = float(0.12);

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load albedo texture
  let albedoTex = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    albedoTex = tex;
    material.map = texture(tex);
    material.needsUpdate = true;
  });

  // Load depth map for displacement
  let depthTex = null;
  ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
    depthTex = tex;
    material.displacementMap = texture(tex);
    material.needsUpdate = true;
  });

  // ---------------------------------------------------------------------------
  // Cinematic primitives
  // ---------------------------------------------------------------------------
  const primitiveInstances = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    const fn = ctx.primitives[prim.name];
    if (fn) {
      // Pass the root group as target
      const instance = fn(root, prim.params);
      primitiveInstances.push(instance);
    }
  }

  // ---------------------------------------------------------------------------
  // Interaction handling (hover lift, click press-down + emit)
  // ---------------------------------------------------------------------------
  const timelines = [];
  const baseY = 0; // mesh starts at y = 0 (after geometry rotation)

  root.userData.handlers = {};

  // Hover enter – rise‑in lift (0.15 scene units)
  root.userData.handlers.hoverEnter = () => {
    const tl = gsap.timeline({ defaults: { ease: 'power3.out', duration: 0.7 } });
    tl.to(mesh.position, { y: baseY + 0.15 });
    timelines.push(tl);
  };

  // Hover leave – return to base
  root.userData.handlers.hoverLeave = () => {
    const tl = gsap.timeline({ defaults: { ease: 'power3.out', duration: 0.7 } });
    tl.to(mesh.position, { y: baseY });
    timelines.push(tl);
  };

  // Click – press‑down + emit navigation event
  root.userData.handlers.click = () => {
    const tl = gsap.timeline({ defaults: { ease: 'back.out(1.7)', duration: 0.12 } });
    tl.to(mesh.scale, { x: 0.97, y: 0.97, z: 0.97 })
      .to(mesh.scale, { x: 1, y: 1, z: 1 });
    timelines.push(tl);
    ctx.emit('hub-features.select', {});
  };

  // ---------------------------------------------------------------------------
  // Cleanup
  // ---------------------------------------------------------------------------
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose textures if they were loaded
    if (albedoTex) albedoTex.dispose();
    if (depthTex) depthTex.dispose();

    // Kill all GSAP timelines
    timelines.forEach((tl) => tl.kill());

    // Cleanup primitives
    primitiveInstances.forEach((inst) => {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    });
  };

  return root;
}
